#!/usr/bin/env python3
"""Generate Arabic B2 Unit 08: history and explanation using a fictional archive."""
from __future__ import annotations
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'reading/arabic/b2/passages.jsonl';LEX=ROOT/'reading/lexicons/arabic.jsonl'
AR_DIAC=re.compile(r'[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]')
def norm(s):return AR_DIAC.sub('',unicodedata.normalize('NFC',s).replace('ـ','').strip())
def lexicon():
 d={}
 for line in LEX.read_text(encoding='utf-8').splitlines():
  if line.strip():
   r=json.loads(line);d.setdefault(norm(r.get('form','')),r)
 return d
PREFERRED={'فقدان':'loss','وضوح':'clarity','مطلع':'beginning; outset','تفاعل':'interaction','مصطلح':'term','كيان':'entity','بعثة':'mission; delegation','جغرافي':'geographic','نية':'intention','مقترح':'proposal'}
def target(f,text,d):
 r=d.get(norm(f))
 if not r:raise KeyError(f)
 return {'id':f"ar-r{r['rank']}",'form':f,'lemma':f,'part_of_speech':r.get('part_of_speech_source'),'intended_sense':PREFERRED[f],'register':'contemporary standard','variety':'MSA','context_strategy':['source_criticism','causal_explanation','category_reflection'],'first_introduced':True,'exposures_in_text':max(1,text.count(f)),'source_lexicon':r.get('source_file'),'source_rank':r['rank'],'beyond_base':False}
def qa(items):
 q=[];a=[]
 for i,(t,p,x,ids) in enumerate(items,1):
  z={'id':f'q{i}','type':t,'prompt':p,'answer_id':f'a{i}'}
  if ids:z['target_ids']=ids
  q.append(z);a.append({'id':f'a{i}','question_id':f'q{i}','answer':x,'explanation':''})
 if len(q)!=10:raise ValueError('ten questions required')
 return q,a
